  if (c("[data-aksave]")){ const a = document.createElement("a"); a.href = SH._url; a.download = (SO.file || "heyvoyo") + (SR === "916" ? "-9x16" : "-1x1") + ".png"; document.body.appendChild(a); a.click(); a.remove(); return; }
