  h += `<div class="ha-buddy">${r ? r.sent ? `✨ <span>${esc(T("你的灯亮了。", "Your light is on."))} <b dir="auto">${esc(r.t)}</b></span>` : `🔒 <span>${esc(T("你选了只留给自己：它在你的这一周里，不上地图。别人的灯照样能点。", "You kept it just for you — it's in your week, not on the map. You can still tap other lights."))}</span>` : `🌙 <span>${esc(T("你还没说，也可以先看看。", "You haven't said yours yet — you can still look around."))}</span>`}</div>`;
