  const R = await loadDay(o.date); R.ans.forEach(x => { if (x.lon == null) return; items.push({id: x.id, nm: x.nm, city: x.city, l: x.l, st: "l", nat: x.nat, t: x.t, p: x.p, real: true, own: x.own, lon: x.lon, lat: x.lat, img: x.img || "", au: x.au ? "data:" + (x.mime || "audio/webm") + ";base64," + x.au : ""}); });
