  if (!VT || VT.date !== tm.date){ VT = {date: tm.date, n: {}, props: [], ld: 0}; loadVotes(tm.date).then(r => { VT.ld = 1; r.votes.filter(v => v.l === LG() && !v.own).forEach(v => { VT.n[v.c] = (VT.n[v.c] || 0) + 1; }); VT.props = r.props.filter(p => p.l === LG()); if (scr === 4 && !pg.hidden) draw(); }); }
